        n, k = map(int, input[idx].split())
        s = input[idx + 1]
        idx += 2
        if k == 1:
            results.append("YES\n0")
            continue
        has_zero = [False] * k
        has_one = [False] * k
        for i in range(n - k + 1):
            substring = s[i:i + k]
            for j in range(k):
                if substring[j] == '0':
                    has_zero[j] = True
                else:
                    has_one[j] = True
        result = []
        possible = True
        for i in range(k):
            if has_zero[i] and has_one[i]:
                result.append('0')
            elif has_zero[i]:
                result.append('0')
            elif has_one[i]:
                result.append('1')
            else:
                possible = False
                break
        if possible:
            results.append("YES\n" + ''.join(result))
        else:
            results.append("NO")
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
